mapper.select:
SELECT c.id AS customer_id, c.name AS customer_name, c.owner_member_id, latest_interaction.id AS interaction_id, latest_interaction.occurred_at AS interaction_at, latest_interaction.body_preview AS interaction_preview FROM customer c JOIN LATERAL ( SELECT i.id, i.occurred_at, i.body_preview FROM interaction i WHERE i.organization_id = c.organization_id AND i.customer_id = c.id AND i.type = 'CHAT_IMPORT' AND i.occurred_at >= #{since} ORDER BY i.occurred_at DESC, i.created_at DESC LIMIT 1 ) latest_interaction ON true WHERE c.organization_id = #{organizationId} AND c.deleted_at IS NULL
AND c.id IN
#{customerId}
AND NOT EXISTS ( SELECT 1 FROM approval a JOIN action_request ar ON ar.organization_id = a.organization_id AND ar.id = a.action_request_id WHERE a.organization_id = c.organization_id AND ar.customer_id = c.id AND a.status = 'PENDING' AND ar.status = 'AWAITING_APPROVAL' ) ORDER BY latest_interaction.occurred_at DESC, c.updated_at DESC LIMIT #{limit}
